-- Bu migration rn_ təhlükəsizlik metadata-sına toxunur; ayrıca razılıq olmadan canlı DB-yə tətbiq edilməməlidir.
WITH his AS (SELECT sistem_id FROM public.rn_modullar WHERE kod='HIS_INPATIENT' LIMIT 1) INSERT INTO public.rn_modullar(sistem_id,parent_id,kod,ad,aciqlama,route,ikon,menyuda_gorunsun,aktiv,sira_no) SELECT sistem_id,NULL,'APP_PATIENT_REGISTRATION','Xəstə qeydiyyatı','L kartlarının yaradılması və idarə edilməsi','/xeste-qeydiyyati','ti ti-user-plus',true,true,5 FROM his ON CONFLICT(kod) DO UPDATE SET sistem_id=EXCLUDED.sistem_id,parent_id=NULL,ad=EXCLUDED.ad,aciqlama=EXCLUDED.aciqlama,route=EXCLUDED.route,ikon=EXCLUDED.ikon,menyuda_gorunsun=true,aktiv=true,sira_no=EXCLUDED.sira_no;
